  const { setNodes, setEdges } = useAgentActions();
  return {
    memoized,
    test1: () => {
      setNodes(resolveCollisions);
    },
    test2: function () {
      setEdges(resolveCollisions);
    },
    test3: function TEST(_, node) {
      console.log(resolveCollisions);
    },
