### Steps to reproduce

1. Have some Flutter code that changes `textInputAction` of a `TextField` at runtime while a TextField is focused and the keyboard is up
2. Do something that changes textInputAction value

### Expected results

iOS keyboard action button style should change to match the new value

### Actual results

iOS keyboard action button style does not change while the TextField remains in focus

### Code sample

<details open><summary>Code sample</summary>

The bug is probably a duplicate of #97253 on a low level, but I am using a higher level API, so I decided to submit a new issue with a different repro.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const TextInputActionReproApp());
}

class TextInputActionReproApp extends StatelessWidget {
  const TextInputActionReproApp({super.key});

  @override
  Widget build(BuildContext context) {
    return const MaterialApp(home: TextInputActionReproPage());
  }
}

class TextInputActionReproPage extends StatefulWidget {
  const TextInputActionReproPage({super.key});

  @override
  State<TextInputActionReproPage> createState() =>
      _TextInputActionReproPageState();
}

class _TextInputActionReproPageState extends State<TextInputActionReproPage> {
  final _controller = TextEditingController();
  final _focusNode = FocusNode();

  String _lastSubmittedValue = '(none)';

  @override
  void dispose() {
    _controller.dispose();
    _focusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final hasText = _controller.text.trim().isNotEmpty;

    // This is correctly recomputed during each build, but changes are not
    // applied to native iOS keyboard until the text field unfocuses.
    final requestedAction = hasText
        ? TextInputAction.send
        : TextInputAction.done;

    return Scaffold(
      appBar: AppBar(title: const Text('TextInputAction Repro')),
      body: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                'Requested textInputAction:',
                style: Theme.of(context).textTheme.titleMedium,
              ),
              const SizedBox(height: 8),
              Text(
                requestedAction.toString(),
                style: Theme.of(context).textTheme.headlineSmall,
              ),
              const SizedBox(height: 24),
              TextField(
                controller: _controller,
                focusNode: _focusNode,
                autofocus: true,
                decoration: const InputDecoration(
                  border: OutlineInputBorder(),
                  labelText: 'Type here, then clear the field',
                ),
                // THIS IS THE BUG: when requestedAction changes, iOS keyboard action
                // does not change until the field is unfocused and refocused.
                textInputAction: requestedAction,
                onChanged: (_) => setState(() {}),
                onSubmitted: (value) {
                  setState(() {
                    _lastSubmittedValue = value;
                  });
                },
              ),
              const SizedBox(height: 16),
              FilledButton(
                onPressed: () {
                  _controller.clear();
                  setState(() {});
                  _focusNode.requestFocus();
                },
                child: const Text('Clear and keep focus'),
              ),
              const SizedBox(height: 24),
              Text('Last submitted value: $_lastSubmittedValue'),
              const Spacer(),
              const Text(
                'On iOS, the label above changes between done and send as the '
                'text changes, but the keyboard return key does not update '
                'until the text input connection is recreated.',
              ),
            ],
          ),
        ),
      ),
    );
  }
}
```

