### Steps to reproduce

Flutter receives address strings via screen constructor arguments.
The screen resolves those strings into LatLng values using Places API and geocoding.
It requests directions and decodes the returned polyline.
It renders the route in-app with GoogleMap, Marker, and Polyline.
When external navigation is needed, it formats a Google Maps URL from those coordinates.
It opens that URL with url_launcher, which hands the route off to Google Maps.

### Expected results

I expect the map in browser to render with step polylines to display a route between points.

### Actual results

No route displayed, but horizontal and some vertical blue lines are displayed on map only in browser.  


Mobile view works as expected.  

### Code sample

<details open><summary>Code sample</summary>

```dart
class AnimalTransportMapScreen extends StatefulWidget with ScreenWidgetMixin {
  final String sourceAddress;
  final String destinationAddress;
  final Map<String, dynamic>? alertData;
  final List<TransportStop>? allStops;

  const AnimalTransportMapScreen({
    super.key,
    required this.sourceAddress,
    required this.destinationAddress,
    this.alertData,
    this.allStops,
  });
}

@override
void initState() {
  super.initState();
  if (_isMultiStop) {
    _resolveMultiStopRoute();
  } else {
    _resolveAddresses();
  }
}

Future<void> _resolveAddresses() async {
  setState(() {
    _loading = true;
    _error = null;
  });
  try {
    LatLng? sourceLatLng;
    final sourceAddr = widget.sourceAddress;

    if (sourceAddr == 'My Location') {
      final pos = await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(
          accuracy: LocationAccuracy.medium,
          timeLimit: Duration(seconds: 10),
        ),
      );
      sourceLatLng = LatLng(pos.latitude, pos.longitude);
    } else if (sourceAddr.isNotEmpty) {
      sourceLatLng = await _fetchPlaceLatLng(sourceAddr)
          .timeout(const Duration(seconds: 8), onTimeout: () => null);

      if (sourceLatLng == null) {
        final src = await locationFromAddress(sourceAddr)
            .timeout(const Duration(seconds: 8), onTimeout: () => []);
        if (src.isNotEmpty) {
          sourceLatLng = LatLng(src.first.latitude, src.first.longitude);
        }
      }
    }

    LatLng? destinationLatLng;
    if (widget.destinationAddress.isNotEmpty) {
      destinationLatLng = await _fetchPlaceLatLng(widget.destinationAddress)
          .timeout(const Duration(seconds: 8), onTimeout: () => null);

      if (destinationLatLng == null) {
        final dst = await locationFromAddress(widget.destinationAddress)
            .timeout(const Duration(seconds: 8), onTimeout: () => []);
        if (dst.isNotEmpty) {
          destinationLatLng = LatLng(dst.first.latitude, dst.first.longitude);
        }
      }
    }

    if (sourceLatLng != null && destinationLatLng != null) {
      _sourceLatLng = sourceLatLng;
      _destinationLatLng = destinationLatLng;
      await _fetchRoutePolyline();
      setState(() {
        _loading = false;
      });
      _moveCamera();
    }
  } catch (e) {
    setState(() {
      _loading = false;
      _error = 'Error resolving addresses: ${e.runtimeType}: ${e.toString()}';
    });
  }
}

Future<LatLng?> _fetchPlaceLatLng(String input) async {
  return MapsApiService.instance.searchTextLatLng(input);
}

GoogleMap(
  initialCameraPosition: CameraPosition(
    target: _sourceLatLng ?? const LatLng(0, 0),
    zoom: 12,
  ),
  onMapCreated: (controller) {
    _mapController = controller;
    if (_isMultiStop && _resolvedStops.isNotEmpty) {
      _moveCameraToAllStops();
    } else {
      _moveCamera();
    }
  },
  markers: _isMultiStop
      ? _buildMultiStopMarkers()
      : {
          if (_sourceLatLng != null)
            Marker(
              markerId: const MarkerId('source'),
              position: _sourceLatLng!,
              infoWindow: const InfoWindow(title: 'Source'),
              icon: BitmapDescriptor.defaultMarkerWithHue(
                BitmapDescriptor.hueBlue,
              ),
            ),
          if (_destinationLatLng != null)
            Marker(
              markerId: const MarkerId('destination'),
              position: _destinationLatLng!,
              infoWindow: const InfoWindow(title: 'Destination'),
              icon: BitmapDescriptor.defaultMarkerWithHue(
                BitmapDescriptor.hueRed,
              ),
            ),
        },
  polylines: _routePoints.length >= 2
      ? {
          Polyline(
            polylineId: const PolylineId('directions'),
            color: Colors.blue,
            width: 5,
            points: _routePoints,
          ),
        }
      : {},
  zoomControlsEnabled: false,
  myLocationEnabled: true,
  myLocationButtonEnabled: true,
)

final originLL = _stops.first.latLng;
final destLL = _stops.last.latLng;
final origin = '${originLL.latitude},${originLL.longitude}';
final destination = '${destLL.latitude},${destLL.longitude}';

var webUrl =
    'https://www.google.com/maps/dir/?api=1'
    '&origin=$origin'
    '&destination=$destination'
    '&travelmode=driving'
    '&dir_action=navigate';

if (_stops.length > 2) {
  final wp = _stops
      .sublist(1, _stops.length - 1)
      .map((s) => '${s.latLng.latitude},${s.latLng.longitude}')
      .join('%7C');
  webUrl += '&waypoints=$wp';
}

if (Platform.isIOS) {
  final dests = _stops.sublist(1);
  final daddr = dests
      .map((s) => '${s.latLng.latitude},${s.latLng.longitude}')
      .join('+to:');
  final appUrl =
      'comgooglemaps://?saddr=$origin&daddr=$daddr&directionsmode=driving'
      '&views=traffic';
  final appUri = Uri.parse(appUrl);
  if (await canLaunchUrl(appUri)) {
    await launchUrl(appUri, mode: LaunchMode.externalApplication);
    return;
  }
}
