    if (user != null) {
      DocumentSnapshot<Map<String, dynamic>> userDoc = await firestore
          .collection('Users')
          .doc(user.uid)
          .get();
      me = AppUser.fromSnapshot(userDoc);
    }
  }

  //for check user exists or not

