        name: auth.currentUser!.displayName ?? '',
        email: auth.currentUser!.email ?? '',
        createdAt: DateFormat('yyyy-MM-dd \n hh:mm a').format(DateTime.now()),
        pushToken: '',
        uid: auth.currentUser!.uid,
        type: 'viewer',
      );

      await firestore
          .collection("Author")
          .doc(auth.currentUser!.uid)
          .set(createUser.toJson());
    }
  }

  // Get all programmers with type '0'
  static Stream<List<AppUser>> getAllUser() {
    return firestore
        .collection('Author')
        .snapshots()
        .map(
          (snapshot) =>
              snapshot.docs.map((doc) => AppUser.fromSnapshot(doc)).toList(),
        );
  }
}
